import json
first=None; last=None; lrs={}
with open('metrics.jsonl') as f:
    for line in f:
        line=line.strip()
        if not line: continue
        try: d=json.loads(line)
        except: continue
        m=d.get('metrics',{})
        if 'actor/weights_l2_norm' in m:
            w=m['actor/weights_l2_norm']
            if first is None: first=(d['step'],w)
            last=(d['step'],w)
        if 'actor/lr' in m: lrs.setdefault(m['actor/lr'],set()).add(d['step'])
print('weights_l2_norm first:', first)
print('weights_l2_norm last :', last)
print('lr values -> n steps:', {k:len(v) for k,v in lrs.items()})
"

